  "name": "state_machine_event_handle",
  "confidence": "medium",
  "docstring": "Handles a pending state-machine event by updating the event flag, acquiring the associated kernel event lock when needed, and invoking state_machine_step.",
  "subsystem": "ke",
  "var_renames": {
    "result": "ctx",
    "v1": "event_state",
    "v3": "event_id"
  },
  "struct_hints": [
    {
      "offset": 114,
      "meaning": "byte event/state pending flag: 1 means resume/process, 2 means new event"
    },
    {
      "offset": 116,
      "meaning": "uint32 event identifier or lock token read when a new event is present"
    },
    {
      "offset": 96,
      "meaning": "kernel event object or context passed to ke_event_lock"
    }
  ]
}
